clearScene();setBig(null);setEq(null);
var M=[[0,0,1],[0,0,1],[1,1,0]];
matrix({rows:3,cols:3,cw:84,ch:58,x:514,y:175,
  cell:function(i,j){return M[i][j];},
  label:"行可换、列也可换"});
arrow(485,235,445,235,"y");
note("行随便换",405,241,"y","end");
note("列也随便换",640,372,"y");
setCap("矩阵模型里，<b>行能换、列也能换</b> —— 两层对称叠在一起。");

clearScene();setBig(null);setEq(null);
boxNode(200,168,420,100,"行 lex 有序 + 列 lex 有序","y");
arrow(640,218,760,218,"y");
boxNode(780,168,320,100,"⇒ 全破了","y");
note("行 lex 破掉全部行对称　✓",640,312,"g");
note("列 lex 破掉全部列对称　✓",640,344,"g");
note("那合起来当然破掉全部？",640,380,"y");
setCap("两个前提<b>都是真的</b>。所以这个推论几乎没人会停下来怀疑。");

clearScene();setBig(null);setEq(null);
var M=[[0,0,1],[0,0,1],[1,1,0]];
matrix({rows:3,cols:3,cw:84,ch:58,x:520,y:170,
  cell:function(i,j){return M[i][j];},
  label:"行从上到下不减，列从左到右不减"});
note("行：001 ≤ 001 ≤ 110",390,368,"g");
note("列：001 ≤ 001 ≤ 110",900,368,"g");
setCap("这就是 <b>双 lex</b>（lex2）：相邻行、相邻列都要求 lex 有序。");

clearScene();setBig(null);setEq(null);
var A=[[0,0,1],[0,0,1],[1,1,0]], B=[[0,1,1],[1,0,0],[1,0,0]];
matrix({rows:3,cols:3,cw:76,ch:54,x:280,y:178,
  cell:function(i,j){return A[i][j];},
  hl:function(i,j){return "hl2";},label:"A"});
matrix({rows:3,cols:3,cw:76,ch:54,x:772,y:178,
  cell:function(i,j){return B[i][j];},
  hl:function(i,j){return "hl2";},label:"B"});
arrow(560,258,740,258,"y");
note("行轮换一位、列也轮换一位",650,232,"y");
note("两张都双 lex 有序，却是同一个类",640,372,"r");
setCap("<b>A 和 B 都满足双 lex，而且互为行列置换的像。</b>破不干净。");

clearScene();setBig(null);setEq(null);
boxNode(150,195,290,96,"512 张","b");
arrow(455,243,545,243,"y");
boxNode(560,195,290,96,"45 张","g");
arrow(865,243,955,243,"y");
boxNode(970,195,290,96,"36 张","g");
note("3×3 的 0/1 矩阵全体",295,325,"b");
note("加了双 lex 之后",705,325,"");
note("本质不同的（下限）",1115,325,"g");
note("全枚举跑出来的，不是估的　·　多出来这 9 张就是全部证据",640,374,"r");
setCap("本质不同的只有 <b>36</b> 个，双 lex 之后还剩 <b>45</b> 个。");

clearScene();setBig(null);setEq(null);
var G=[["","会不会丢解","破不破得干净"],
       ["只排行","不丢","行对称：干净"],
       ["只排列","不丢","列对称：干净"],
       ["双 lex","不丢","复合对称：不干净"]];
matrix({rows:4,cols:3,cw:230,ch:46,x:295,y:178,
  cell:function(i,j){return G[i][j];},
  hl:function(i,j){return i===3&&j===2?"hl3":"";},
  label:"两件事必须分开问"});
setCap("<b>sound ≠ complete</b>。双 lex 一个解都不丢，但就是破不干净。");

clearScene();setBig(null);setEq(null);
var X=[[1,2,3,1,2],[2,1,3,2,1]];
gridworld({rows:2,cols:5,cs:66,x:475,y:186,
  cls:function(i,j){return i===0?"g":"";},
  val:function(i,j){return ""+X[i][j];}});
note("同一张地图的两个「解」（五个区域的颜色编号）",640,166,"");
note("第二行只是把 1 和 2 对调了名字",640,356,"y");
setCap("求解器会把这两行当成<b>两个不同的解</b>，各搜一遍。");

clearScene();setBig(null);setEq(null);
boxNode(215,170,430,100,"值对称？也上 lex_lesseq","y");
arrow(665,220,780,220,"r");
boxNode(800,170,300,100,"打不中","r");
note("lex 管的是「变量按什么顺序排」",950,310,"");
note("换名动的是「值叫什么名字」",950,342,"r");
setCap("两边都叫「对称」，可<b>动的东西不是一回事</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:206,r:32,gap:250,items:[
 {label:"1 2 1 3",sub:"1、2、3 依次首次出现",state:"on"},
 {label:"2 1 2 3",sub:"2 比 1 先出场",state:"dead"},
 {label:"1 3 1 2",sub:"3 比 2 先出场",state:"dead"},
 {label:"3 1 3 2",sub:"3 最先出场",state:"dead"}],
 caption:"6 份拷贝 ⇒ 恰好留 1 份"});
setCap("规则只认「<b>谁先出场</b>」，于是每一类里恰好留下一份。");

clearScene();setBig(null);setEq(null);
boxNode(355,162,570,80,"value_precede_chain([1,2,3], color)","g");
note("手册 4.2.2.2，和 lex_lesseq 同一节",640,296,"");
note("出处：Law & Lee，CP 2004",640,328,"y");
note("Jimmy Lee 正是这门课的另一位主讲",640,364,"");
setCap("值对称有<b>自己的全局约束</b>，不是拿 lex 去凑。");

clearScene();setBig(null);setEq(null);
var G=[["对称的类型","动的是什么","该用的刀"],
       ["变量对称","哪个变量","lex_lesseq"],
       ["值对称","值叫什么名字","value_precede_chain"]];
matrix({rows:3,cols:3,cw:250,ch:54,x:265,y:182,
  cell:function(i,j){return G[i][j];},
  hl:function(i,j){return i===2&&j===2?"hl2":"";},
  label:"先认类型，再选刀"});
setCap("用错刀不是慢一点 —— 是<s>那层对称一点都没破到</s>。");

clearScene();setBig(null);setEq(null);
bars({vals:[7,5,9,4],max:10,x:380,y:356,w:520,h:150,
  cls:function(i){return i===0?"g":(i===1?"r":"");}});
note("a 重3 值7",432,380,"g");
note("b 重4 值5",562,380,"r");
note("c 重5 值9",692,380,"");
note("d 重6 值4",822,380,"");
setCap("a 比 b <b>更轻</b>，价值还<b>更高</b>。那「装 b 不装 a」的方案，意义何在？");

clearScene();setBig(null);setEq(null);
boxNode(215,170,430,100,"支配 = 更强的对称破缺","y");
arrow(665,220,780,220,"r");
boxNode(800,170,300,100,"不一样","r");
note("都在合法地砍，这没错",950,310,"");
note("但承诺的东西完全不同",950,342,"r");
setCap("两者确实都在合法地砍。差别<b>不在砍多少，在保证什么</b>。");

clearScene();setBig(null);setEq(null);
var G=[["","对称破缺","支配破缺"],
       ["保证留下","每个类恰好一个","至少一个最优解"],
       ["要目标函数吗","不要","要"],
       ["能枚举全部解吗","能","不能"]];
matrix({rows:4,cols:3,cw:240,ch:48,x:280,y:172,
  cell:function(i,j){return G[i][j];},
  hl:function(i,j){return i===3&&j===2?"hl3":"";},
  label:"同样是砍，承诺的东西不一样"});
setCap("支配只答应<b>至少留下一个最优解</b> —— 别的解它一概不保。");

clearScene();setBig(null);setEq(null);
boxNode(185,170,420,104,"这一讲：结构性的","b");
note("从模型就能读出来",395,316,"");
note("搜索开始前就加好",395,348,"b");
boxNode(725,170,420,104,"L11：学来的","v");
note("撞上矛盾才推得出",935,316,"");
note("搜索当中才会有",935,348,"v");
arrow(620,222,710,222,"y");
setCap("两边都 sound，但<b>凭据不同</b>：一个先验，一个后验 —— 而且<em>可以叠着用</em>。");
